  judgment_id text not null,
  choice_id text not null,
  signal_ids text[] not null check (cardinality(signal_ids) > 0),
  misconception_key text not null check (char_length(trim(misconception_key)) > 0),
  misconception_title text not null check (char_length(trim(misconception_title)) > 0),
  teacher_note text not null check (char_length(trim(teacher_note)) > 0),
  created_at timestamptz not null default now(),
  primary key (set_key, version, judgment_id, choice_id),
  foreign key (set_key, version)
    references public.diagnosis_sets(set_key, version)
