create or replace function public.assert_distractor_note_coverage(
  p_set_key text,
  p_version text
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  diagnosis_content jsonb;
  expected_count integer;
  actual_count integer;
begin
  select content
  into diagnosis_content
  from public.diagnosis_sets
  where set_key = p_set_key
    and version = p_version;

  if diagnosis_content is null then
    raise exception 'published diagnosis set % at % was not found',
      p_set_key, p_version;
  end if;

  select count(*)
  into expected_count
  from jsonb_array_elements(diagnosis_content -> 'judgments') judgment,
       jsonb_array_elements(judgment -> 'choices') choice
  where not (choice ->> 'correct')::boolean;

  select count(*)
  into actual_count
  from public.diagnosis_distractor_notes note
  where note.set_key = p_set_key
    and note.version = p_version;

  if actual_count <> expected_count then
    raise exception 'distractor note count mismatch: expected %, found %',
      expected_count, actual_count;
  end if;

  if exists (
    select 1
    from jsonb_array_elements(diagnosis_content -> 'judgments') judgment,
         jsonb_array_elements(judgment -> 'choices') choice
    where not (choice ->> 'correct')::boolean
      and not exists (
        select 1
        from public.diagnosis_distractor_notes note
        where note.set_key = p_set_key
          and note.version = p_version
          and note.judgment_id = judgment ->> 'id'
          and note.choice_id = choice ->> 'id'
          and note.signal_ids = array(
            select signal_id #>> '{}'
            from jsonb_array_elements(choice -> 'signalIds') signal_id
            order by signal_id #>> '{}'
          )
      )
  ) then
    raise exception 'a non-correct choice is missing its exact teacher note';
  end if;

  if exists (
    select 1
    from public.diagnosis_distractor_notes note
    where note.set_key = p_set_key
      and note.version = p_version
      and not exists (
        select 1
        from jsonb_array_elements(diagnosis_content -> 'judgments') judgment,
             jsonb_array_elements(judgment -> 'choices') choice
        where judgment ->> 'id' = note.judgment_id
          and choice ->> 'id' = note.choice_id
          and not (choice ->> 'correct')::boolean
      )
  ) then
    raise exception 'an extra or correct-choice teacher note was found';
  end if;
end;
$$;

