from jsonb_to_recordset($notes$[{"choice_id":"three-hundred","judgment_id":"g4s1-large-01","misconception_key":"large-number.place-value.place-shifted-right","misconception_title":"목표 자리를 한 칸 오른쪽의 작은 자리로 옮김","set_key":"grade4-semester1","signal_ids":["large-number.place-value"],"teacher_note":"천의 자리의 3을 한 칸 오른쪽인 백의 자리 값으로 읽었습니다.","version":"1.3.0"},{"choice_id":"thirty-thousand","judgment_id":"g4s1-large-01","misconception_key":"large-number.place-value.place-shifted-left","misconception_title":"목표 자리를 한 칸 왼쪽의 큰 자리로 옮김","set_key":"grade4-semester1","signal_ids":["large-number.place-value"],"teacher_note":"천의 자리의 3을 한 칸 왼쪽인 만의 자리 값으로 읽었습니다.","version":"1.3.0"},{"choice_id":"thousands-place","judgment_id":"g4s1-large-02","misconception_key":"large-number.place-value.place-shifted-right","misconception_title":"목표 자리를 한 칸 오른쪽의 작은 자리로 옮김","set_key":"grade4-semester1","signal_ids":["large-number.place-value"],"teacher_note":"자리표의 숫자 4를 한 칸 오른쪽의 작은 자리로 읽었습니다.","version":"1.3.0"},{"choice_id":"hundred-thousands-place","judgment_id":"g4s1-large-02","misconception_key":"large-number.place-value.place-shifted-left","misconception_title":"목표 자리를 한 칸 왼쪽의 큰 자리로 옮김","set_key":"grade4-semester1","signal_ids":["large-number.place-value"],"teacher_note":"자리표의 숫자 4를 한 칸 왼쪽의 큰 자리로 읽었습니다.","version":"1.3.0"},{"choice_id":"ten-times","judgment_id":"g4s1-large-03","misconception_key":"large-number.positional-notation.place-gap-under-counted","misconception_title":"자리 사이 간격을 한 단계 적게 세어 계산함","set_key":"grade4-semester1","signal_ids":["large-number.positional-notation"],"teacher_note":"만의 자리와 백의 자리 사이의 두 단계 차이를 한 단계로 줄였습니다.","version":"1.3.0"},{"choice_id":"same-value","judgment_id":"g4s1-large-03","misconception_key":"large-number.positional-notation.same-digit-same-value","misconception_title":"숫자가 같으면 자리와 관계없이 값도 같다고 봄","set_key":"grade4-semester1","signal_ids":["large-number.positional-notation"],"teacher_note":"두 자리에 적힌 숫자가 모두 5라는 겉모습만 보고 값도 같다고 보았습니다.","version":"1.3.0"},{"choice_id":"hundred-times","judgment_id":"g4s1-large-04","misconception_key":"large-number.positional-notation.place-gap-under-counted","misconception_title":"자리 사이 간격을 한 단계 적게 세어 계산함","set_key":"grade4-semester1","signal_ids":["large-number.positional-notation"],"teacher_note":"천의 자리에서 백만의 자리까지 세 칸 옮기는 것을 두 칸으로 줄였습니다.","version":"1.3.0"},{"choice_id":"same-value","judgment_id":"g4s1-large-04","misconception_key":"large-number.positional-notation.same-digit-same-value","misconception_title":"숫자가 같으면 자리와 관계없이 값도 같다고 봄","set_key":"grade4-semester1","signal_ids":["large-number.positional-notation"],"teacher_note":"숫자 카드가 같은 2라는 이유로 옮긴 뒤에도 값이 그대로라고 보았습니다.","version":"1.3.0"},{"choice_id":"thousands-reading","judgment_id":"g4s1-large-05","misconception_key":"large-number.read-write.ten-thousands-read-as-thousands","misconception_title":"만 단위를 천 단위로 한 자리 낮춰 나타냄","set_key":"grade4-semester1","signal_ids":["large-number.read-write"],"teacher_note":"70,000의 7을 만의 자리 대신 천의 자리로 낮추어 읽었습니다.","version":"1.3.0"},{"choice_id":"hundreds-omitted","judgment_id":"g4s1-large-05","misconception_key":"large-number.read-write.nonzero-place-omitted","misconception_title":"0이 아닌 한 자리의 값을 읽거나 쓸 때 빠뜨림","set_key":"grade4-semester1","signal_ids":["large-number.read-write"],"teacher_note":"백의 자리 숫자 3이 나타내는 300을 읽지 않았습니다.","version":"1.3.0"},{"choice_id":"8530","judgment_id":"g4s1-large-06","misconception_key":"large-number.read-write.ten-thousands-read-as-thousands","misconception_title":"만 단위를 천 단위로 한 자리 낮춰 나타냄","set_key":"grade4-semester1","signal_ids":["large-number.read-write"],"teacher_note":"팔만의 80,000을 8,000으로 한 자리 낮추어 숫자로 썼습니다.","version":"1.3.0"},{"choice_id":"80030","judgment_id":"g4s1-large-06","misconception_key":"large-number.read-write.nonzero-place-omitted","misconception_title":"0이 아닌 한 자리의 값을 읽거나 쓸 때 빠뜨림","set_key":"grade4-semester1","signal_ids":["large-number.read-write"],"teacher_note":"오백이 나타내는 백의 자리 값 500을 숫자에서 빠뜨렸습니다.","version":"1.3.0"},{"choice_id":"52410","judgment_id":"g4s1-large-07","misconception_key":"large-number.sequence.step-size-one-place-too-small","misconception_title":"뛰어 세는 크기를 한 자리 작게 사용함","set_key":"grade4-semester1","signal_ids":["large-number.sequence"],"teacher_note":"100씩 커지는 계열을 10씩 커지는 계열로 줄여 이어 썼습니다.","version":"1.3.0"},{"choice_id":"52300","judgment_id":"g4s1-large-07","misconception_key":"large-number.sequence.sequence-direction-reversed","misconception_title":"커지는 규칙과 작아지는 규칙의 방향을 바꿈","set_key":"grade4-semester1","signal_ids":["large-number.sequence"],"teacher_note":"앞의 수보다 커져야 하는데 100을 거꾸로 빼었습니다.","version":"1.3.0"},{"choice_id":"minus-50","judgment_id":"g4s1-large-08","misconception_key":"large-number.sequence.step-size-one-place-too-small","misconception_title":"뛰어 세는 크기를 한 자리 작게 사용함","set_key":"grade4-semester1","signal_ids":["large-number.sequence"],"teacher_note":"이웃한 수의 차 500을 한 자리 작은 50으로 보았습니다.","version":"1.3.0"},{"choice_id":"plus-500","judgment_id":"g4s1-large-08","misconception_key":"large-number.sequence.sequence-direction-reversed","misconception_title":"커지는 규칙과 작아지는 규칙의 방향을 바꿈","set_key":"grade4-semester1","signal_ids":["large-number.sequence"],"teacher_note":"수가 실제로 작아지는 순서를 커지는 순서로 반대로 설명했습니다.","version":"1.3.0"},{"choice_id":"64208","judgment_id":"g4s1-large-09","misconception_key":"large-number.compare.first-different-place-skipped","misconception_title":"처음 다른 자리를 건너뛰고 더 낮은 자리를 먼저 비교함","set_key":"grade4-semester1","signal_ids":["large-number.compare"],"teacher_note":"처음 다른 백의 자리를 건너뛰고 일의 자리 숫자를 먼저 비교했습니다.","version":"1.3.0"},{"choice_id":"same","judgment_id":"g4s1-large-09","misconception_key":"large-number.compare.highest-place-only","misconception_title":"가장 높은 한 자리만 같으면 두 수 전체도 같다고 봄","set_key":"grade4-semester1","signal_ids":["large-number.compare"],"teacher_note":"만의 자리 숫자 6이 같다는 사실만 보고 나머지 자리를 비교하지 않았습니다.","version":"1.3.0"},{"choice_id":"85720","judgment_id":"g4s1-large-10","misconception_key":"large-number.compare.first-different-place-skipped","misconception_title":"처음 다른 자리를 건너뛰고 더 낮은 자리를 먼저 비교함","set_key":"grade4-semester1","signal_ids":["large-number.compare"],"teacher_note":"87,250과 85,720에서 처음 다른 천의 자리를 건너뛰고 백의 자리를 비교했습니다.","version":"1.3.0"},{"choice_id":"same","judgment_id":"g4s1-large-10","misconception_key":"large-number.compare.highest-place-only","misconception_title":"가장 높은 한 자리만 같으면 두 수 전체도 같다고 봄","set_key":"grade4-semester1","signal_ids":["large-number.compare"],"teacher_note":"세 수의 만의 자리 숫자 8이 같다는 사실만 보고 모두 같은 수라고 보았습니다.","version":"1.3.0"},{"choice_id":"ones-first","judgment_id":"g4s1-large-11","misconception_key":"large-number.compare-reasoning.lower-place-used-as-reason","misconception_title":"처음 다른 자리보다 낮은 자리를 비교 근거로 사용함","set_key":"grade4-semester1","signal_ids":["large-number.compare-reasoning"],"teacher_note":"처음 다른 백의 자리보다 낮은 일의 자리를 비교 근거로 사용했습니다.","version":"1.3.0"},{"choice_id":"reversed-order","judgment_id":"g4s1-large-11","misconception_key":"large-number.compare-reasoning.digit-order-reversed","misconception_title":"처음 다른 자리에서 작은 숫자가 있는 수를 더 크다고 설명함","set_key":"grade4-semester1","signal_ids":["large-number.compare-reasoning"],"teacher_note":"처음 다른 백의 자리에서 작은 숫자 6이 있는 수를 더 크다고 설명했습니다.","version":"1.3.0"},{"choice_id":"ones-first","judgment_id":"g4s1-large-12","misconception_key":"large-number.compare-reasoning.lower-place-used-as-reason","misconception_title":"처음 다른 자리보다 낮은 자리를 비교 근거로 사용함","set_key":"grade4-semester1","signal_ids":["large-number.compare-reasoning"],"teacher_note":"결과는 바로 고쳤지만 처음 다른 백의 자리 대신 일의 자리를 근거로 들었습니다.","version":"1.3.0"},{"choice_id":"reversed-order","judgment_id":"g4s1-large-12","misconception_key":"large-number.compare-reasoning.digit-order-reversed","misconception_title":"처음 다른 자리에서 작은 숫자가 있는 수를 더 크다고 설명함","set_key":"grade4-semester1","signal_ids":["large-number.compare-reasoning"],"teacher_note":"처음 다른 백의 자리에서 4가 더 큰데도 그 수가 더 작다고 설명했습니다.","version":"1.3.0"},{"choice_id":"ray-length-large","judgment_id":"g4s1-angle-01","misconception_key":"angle.right-angle.ray-length-as-size","misconception_title":"변의 길이를 각의 크기나 자격으로 봄","set_key":"grade4-semester1","signal_ids":["angle.right-angle"],"teacher_note":"긴 변이 있으면 각이 커진다고 보아 직각을 직각보다 큰 각으로 판단했습니다.","version":"1.3.0"},{"choice_id":"unequal-rays","judgment_id":"g4s1-angle-01","misconception_key":"angle.right-angle.unequal-rays-block-right-angle","misconception_title":"두 변의 길이가 달라야 하거나 같아야 한다는 조건을 덧붙임","set_key":"grade4-semester1","signal_ids":["angle.right-angle"],"teacher_note":"두 변의 길이가 같을 때만 직각이라는 조건을 덧붙였습니다.","version":"1.3.0"},{"choice_id":"long-ray-only","judgment_id":"g4s1-angle-02","misconception_key":"angle.right-angle.ray-length-as-size","misconception_title":"변의 길이를 각의 크기나 자격으로 봄","set_key":"grade4-semester1","signal_ids":["angle.right-angle"],"teacher_note":"길이가 긴 반직선만 변으로 인정했습니다.","version":"1.3.0"},{"choice_id":"equal-rays-required","judgment_id":"g4s1-angle-02","misconception_key":"angle.right-angle.unequal-rays-block-right-angle","misconception_title":"두 변의 길이가 달라야 하거나 같아야 한다는 조건을 덧붙임","set_key":"grade4-semester1","signal_ids":["angle.right-angle"],"teacher_note":"꼭짓점의 정의에 두 변의 길이가 같아야 한다는 조건을 붙였습니다.","version":"1.3.0"},{"choice_id":"acute","judgment_id":"g4s1-angle-03","misconception_key":"angle.classify.right-angle-comparison-reversed","misconception_title":"직각 기준과의 크고 작음을 반대로 판단함","set_key":"grade4-semester1","signal_ids":["angle.classify"],"teacher_note":"직각 기준선보다 더 벌어진 각을 덜 벌어진 것으로 반대로 읽었습니다.","version":"1.3.0"},{"choice_id":"right","judgment_id":"g4s1-angle-03","misconception_key":"angle.classify.near-right-angle-called-right","misconception_title":"직각에 가까우면 모두 직각으로 처리함","set_key":"grade4-semester1","signal_ids":["angle.classify"],"teacher_note":"직각보다 35도 큰 각을 직각에 가깝다고 보아 직각으로 처리했습니다.","version":"1.3.0"},{"choice_id":"more-than-right","judgment_id":"g4s1-angle-04","misconception_key":"angle.classify.right-angle-comparison-reversed","misconception_title":"직각 기준과의 크고 작음을 반대로 판단함","set_key":"grade4-semester1","signal_ids":["angle.classify"],"teacher_note":"기준선보다 덜 벌어진 각을 더 벌어진 것으로 반대로 읽었습니다.","version":"1.3.0"},{"choice_id":"almost-right","judgment_id":"g4s1-angle-04","misconception_key":"angle.classify.near-right-angle-called-right","misconception_title":"직각에 가까우면 모두 직각으로 처리함","set_key":"grade4-semester1","signal_ids":["angle.classify"],"teacher_note":"직각보다 5도 작은 각을 차이가 작다는 이유로 직각으로 처리했습니다.","version":"1.3.0"},{"choice_id":"55-degrees","judgment_id":"g4s1-angle-05","misconception_key":"angle.protractor-measure.inner-outer-scale-confused","misconception_title":"안쪽·바깥쪽 눈금 방향을 바꾸어 읽음","set_key":"grade4-semester1","signal_ids":["angle.protractor-measure"],"teacher_note":"안쪽 눈금 대신 바깥쪽 눈금을 읽었습니다.","version":"1.3.0"},{"choice_id":"cannot-measure","judgment_id":"g4s1-angle-05","misconception_key":"angle.protractor-measure.baseline-alignment-misjudged","misconception_title":"0 눈금 정렬 상태를 반대로 판단함","set_key":"grade4-semester1","signal_ids":["angle.protractor-measure"],"teacher_note":"0 눈금이 한 변에 맞게 놓여 있는데 어긋났다고 반대로 판단했습니다.","version":"1.3.0"},{"choice_id":"read-other-scale","judgment_id":"g4s1-angle-06","misconception_key":"angle.protractor-measure.inner-outer-scale-confused","misconception_title":"안쪽·바깥쪽 눈금 방향을 바꾸어 읽음","set_key":"grade4-semester1","signal_ids":["angle.protractor-measure"],"teacher_note":"0 눈금을 다시 맞추지 않고 반대쪽 눈금을 읽어 해결하려 했습니다.","version":"1.3.0"},{"choice_id":"center-only","judgment_id":"g4s1-angle-06","misconception_key":"angle.protractor-measure.baseline-alignment-misjudged","misconception_title":"0 눈금 정렬 상태를 반대로 판단함","set_key":"grade4-semester1","signal_ids":["angle.protractor-measure"],"teacher_note":"0 눈금이 어긋났는데 중심만 맞으면 된다고 반대로 판단했습니다.","version":"1.3.0"},{"choice_id":"about-90","judgment_id":"g4s1-angle-07","misconception_key":"angle.estimate.right-angle-value-mistaken","misconception_title":"직각을 기준으로 삼지 못하고 크기를 90도 쪽으로 끌어당김","set_key":"grade4-semester1","signal_ids":["angle.estimate"],"teacher_note":"직각 기준선과 겹치지 않는 각을 직각으로 끌어당겼습니다.","version":"1.3.0"},{"choice_id":"about-135","judgment_id":"g4s1-angle-07","misconception_key":"angle.estimate.estimate-direction-reversed","misconception_title":"직각보다 크고 작음의 방향을 반대로 어림함","set_key":"grade4-semester1","signal_ids":["angle.estimate"],"teacher_note":"직각보다 작은 각을 큰 쪽으로 뒤집어 어림했습니다.","version":"1.3.0"},{"choice_id":"about-100","judgment_id":"g4s1-angle-08","misconception_key":"angle.estimate.right-angle-value-mistaken","misconception_title":"직각을 기준으로 삼지 못하고 크기를 90도 쪽으로 끌어당김","set_key":"grade4-semester1","signal_ids":["angle.estimate"],"teacher_note":"직각에 가까운 값으로 끌어당겨 어림했습니다.","version":"1.3.0"},{"choice_id":"about-30","judgment_id":"g4s1-angle-08","misconception_key":"angle.estimate.estimate-direction-reversed","misconception_title":"직각보다 크고 작음의 방향을 반대로 어림함","set_key":"grade4-semester1","signal_ids":["angle.estimate"],"teacher_note":"직각보다 큰 각을 작은 쪽으로 뒤집어 어림했습니다.","version":"1.3.0"},{"choice_id":"90-degrees","judgment_id":"g4s1-angle-09","misconception_key":"angle.triangle-angle-sum.right-angle-assumed","misconception_title":"삼각형에 직각이 있다고 가정함","set_key":"grade4-semester1","signal_ids":["angle.triangle-angle-sum"],"teacher_note":"삼각형에 직각이 있다고 가정했습니다.","version":"1.3.0"},{"choice_id":"25-degrees","judgment_id":"g4s1-angle-09","misconception_key":"angle.triangle-angle-sum.known-angle-difference-used","misconception_title":"알려진 두 각의 차를 근거로 사용함","set_key":"grade4-semester1","signal_ids":["angle.triangle-angle-sum"],"teacher_note":"알려진 두 각의 차를 나머지 각으로 사용했습니다.","version":"1.3.0"},{"choice_id":"no-right-angle-needed","judgment_id":"g4s1-angle-10","misconception_key":"angle.triangle-angle-sum.right-angle-assumed","misconception_title":"삼각형에 직각이 있다고 가정함","set_key":"grade4-semester1","signal_ids":["angle.triangle-angle-sum"],"teacher_note":"직각이 없으면 세 각의 합 조건을 확인하지 않아도 된다고 보았습니다.","version":"1.3.0"},{"choice_id":"difference-is-enough","judgment_id":"g4s1-angle-10","misconception_key":"angle.triangle-angle-sum.known-angle-difference-used","misconception_title":"알려진 두 각의 차를 근거로 사용함","set_key":"grade4-semester1","signal_ids":["angle.triangle-angle-sum"],"teacher_note":"세 각의 합 대신 가장 큰 각과 작은 각의 차를 근거로 삼았습니다.","version":"1.3.0"},{"choice_id":"90-degrees","judgment_id":"g4s1-angle-11","misconception_key":"angle.quadrilateral-angle-sum.quadrilateral-treated-as-right-angles","misconception_title":"사각형의 네 각을 모두 직각으로 가정함","set_key":"grade4-semester1","signal_ids":["angle.quadrilateral-angle-sum"],"teacher_note":"사각형의 네 각을 모두 직각으로 가정했습니다.","version":"1.3.0"},{"choice_id":"5-degrees","judgment_id":"g4s1-angle-11","misconception_key":"angle.quadrilateral-angle-sum.triangle-rule-applied-to-quadrilateral","misconception_title":"사각형에 삼각형의 합 규칙을 그대로 적용함","set_key":"grade4-semester1","signal_ids":["angle.quadrilateral-angle-sum"],"teacher_note":"사각형에 삼각형의 합 규칙을 적용했습니다.","version":"1.3.0"},{"choice_id":"one-triangle-sum","judgment_id":"g4s1-angle-12","misconception_key":"angle.quadrilateral-angle-sum.triangle-rule-applied-to-quadrilateral","misconception_title":"사각형에 삼각형의 합 규칙을 그대로 적용함","set_key":"grade4-semester1","signal_ids":["angle.quadrilateral-angle-sum"],"teacher_note":"삼각형이 두 개인데 하나 몫만 더했습니다.","version":"1.3.0"},{"choice_id":"all-right-angles","judgment_id":"g4s1-angle-12","misconception_key":"angle.quadrilateral-angle-sum.quadrilateral-treated-as-right-angles","misconception_title":"사각형의 네 각을 모두 직각으로 가정함","set_key":"grade4-semester1","signal_ids":["angle.quadrilateral-angle-sum"],"teacher_note":"네 각을 모두 직각으로 가정해 90도를 네 번 더하려 했습니다.","version":"1.3.0"},{"choice_id":"left-three","judgment_id":"g4s1-transform-01","misconception_key":"figure-transform.slide.slide-direction-reversed","misconception_title":"도형을 민 방향을 반대로 판단함","set_key":"grade4-semester1","signal_ids":["figure-transform.slide"],"teacher_note":"처음 도형에서 나중 도형으로 간 가로 방향을 반대로 읽었습니다.","version":"1.3.0"},{"choice_id":"right-four","judgment_id":"g4s1-transform-01","misconception_key":"figure-transform.slide.start-cell-counted","misconception_title":"출발 칸을 포함하여 이동 칸 수를 하나 크게 셈","set_key":"grade4-semester1","signal_ids":["figure-transform.slide"],"teacher_note":"출발 칸을 첫 칸으로 포함해 실제 이동보다 한 칸 크게 세었습니다.","version":"1.3.0"},{"choice_id":"up-three","judgment_id":"g4s1-transform-02","misconception_key":"figure-transform.slide.slide-direction-reversed","misconception_title":"도형을 민 방향을 반대로 판단함","set_key":"grade4-semester1","signal_ids":["figure-transform.slide"],"teacher_note":"처음 도형에서 나중 도형으로 간 세로 방향을 반대로 읽었습니다.","version":"1.3.0"},{"choice_id":"down-four","judgment_id":"g4s1-transform-02","misconception_key":"figure-transform.slide.start-cell-counted","misconception_title":"출발 칸을 포함하여 이동 칸 수를 하나 크게 셈","set_key":"grade4-semester1","signal_ids":["figure-transform.slide"],"teacher_note":"세로 이동에서 시작 행까지 세어 실제보다 한 칸 더 움직였다고 보았습니다.","version":"1.3.0"},{"choice_id":"slide-right","judgment_id":"g4s1-transform-03","misconception_key":"figure-transform.flip-left-right.flip-treated-as-slide","misconception_title":"좌우가 바뀐 도형을 방향 그대로 옮긴 것으로 판단함","set_key":"grade4-semester1","signal_ids":["figure-transform.flip-left-right"],"teacher_note":"도형의 꺾인 방향과 표식 위치가 좌우로 바뀐 사실을 무시했습니다.","version":"1.3.0"},{"choice_id":"flip-up-down","judgment_id":"g4s1-transform-03","misconception_key":"figure-transform.flip-left-right.wrong-flip-axis","misconception_title":"세로 기준선 대신 가로 기준선으로 뒤집었다고 판단함","set_key":"grade4-semester1","signal_ids":["figure-transform.flip-left-right"],"teacher_note":"그림에 표시된 세로 기준선을 가로 기준선으로 바꾸어 생각했습니다.","version":"1.3.0"},{"choice_id":"same-shape-slide","judgment_id":"g4s1-transform-04","misconception_key":"figure-transform.flip-left-right.flip-treated-as-slide","misconception_title":"좌우가 바뀐 도형을 방향 그대로 옮긴 것으로 판단함","set_key":"grade4-semester1","signal_ids":["figure-transform.flip-left-right"],"teacher_note":"도형 안 표식이 반대쪽으로 간 사실을 무시하고 모양과 방향이 그대로라고 보았습니다.","version":"1.3.0"},{"choice_id":"mirror-on-horizontal","judgment_id":"g4s1-transform-04","misconception_key":"figure-transform.flip-left-right.wrong-flip-axis","misconception_title":"세로 기준선 대신 가로 기준선으로 뒤집었다고 판단함","set_key":"grade4-semester1","signal_ids":["figure-transform.flip-left-right"],"teacher_note":"세로 점선을 보면서도 가로선을 기준으로 뒤집었다고 판단했습니다.","version":"1.3.0"},{"choice_id":"slide-down","judgment_id":"g4s1-transform-05","misconception_key":"figure-transform.flip-up-down.flip-treated-as-slide","misconception_title":"위아래가 바뀐 도형을 방향 그대로 옮긴 것으로 판단함","set_key":"grade4-semester1","signal_ids":["figure-transform.flip-up-down"],"teacher_note":"도형의 꺾인 방향과 표식 위치가 위아래로 바뀐 사실을 무시했습니다.","version":"1.3.0"},{"choice_id":"flip-left-right","judgment_id":"g4s1-transform-05","misconception_key":"figure-transform.flip-up-down.wrong-flip-axis","misconception_title":"가로 기준선 대신 세로 기준선으로 뒤집었다고 판단함","set_key":"grade4-semester1","signal_ids":["figure-transform.flip-up-down"],"teacher_note":"그림에 표시된 가로 기준선을 세로 기준선으로 바꾸어 생각했습니다.","version":"1.3.0"},{"choice_id":"same-shape-down","judgment_id":"g4s1-transform-06","misconception_key":"figure-transform.flip-up-down.flip-treated-as-slide","misconception_title":"위아래가 바뀐 도형을 방향 그대로 옮긴 것으로 판단함","set_key":"grade4-semester1","signal_ids":["figure-transform.flip-up-down"],"teacher_note":"표식의 위아래 위치가 달라진 사실을 빼고 도형을 통째로 내린 것으로 보았습니다.","version":"1.3.0"},{"choice_id":"mirror-on-vertical","judgment_id":"g4s1-transform-06","misconception_key":"figure-transform.flip-up-down.wrong-flip-axis","misconception_title":"가로 기준선 대신 세로 기준선으로 뒤집었다고 판단함","set_key":"grade4-semester1","signal_ids":["figure-transform.flip-up-down"],"teacher_note":"가로 점선을 보면서도 세로선을 기준으로 뒤집었다고 판단했습니다.","version":"1.3.0"},{"choice_id":"counterclockwise-quarter","judgment_id":"g4s1-transform-07","misconception_key":"figure-transform.rotate.turn-direction-reversed","misconception_title":"시계 방향과 시계 반대 방향을 바꾸어 판단함","set_key":"grade4-semester1","signal_ids":["figure-transform.rotate"],"teacher_note":"중심 위쪽의 표식이 중심 오른쪽으로 간 회전 방향을 반대로 읽었습니다.","version":"1.3.0"},{"choice_id":"slide-right-two","judgment_id":"g4s1-transform-07","misconception_key":"figure-transform.rotate.rotation-treated-as-slide","misconception_title":"중심을 고정한 돌리기를 도형 전체의 밀기로 판단함","set_key":"grade4-semester1","signal_ids":["figure-transform.rotate"],"teacher_note":"중심과의 위치 관계와 도형의 방향 변화를 무시하고 가로 이동으로 보았습니다.","version":"1.3.0"},{"choice_id":"clockwise-quarter","judgment_id":"g4s1-transform-08","misconception_key":"figure-transform.rotate.turn-direction-reversed","misconception_title":"시계 방향과 시계 반대 방향을 바꾸어 판단함","set_key":"grade4-semester1","signal_ids":["figure-transform.rotate"],"teacher_note":"중심 오른쪽 아래의 표식이 중심 위쪽으로 간 회전 방향을 반대로 읽었습니다.","version":"1.3.0"},{"choice_id":"slide-left-two","judgment_id":"g4s1-transform-08","misconception_key":"figure-transform.rotate.rotation-treated-as-slide","misconception_title":"중심을 고정한 돌리기를 도형 전체의 밀기로 판단함","set_key":"grade4-semester1","signal_ids":["figure-transform.rotate"],"teacher_note":"중심을 둘러싼 위치 변화와 도형 방향의 변화를 무시했습니다.","version":"1.3.0"},{"choice_id":"left-four","judgment_id":"g4s1-transform-09","misconception_key":"figure-transform.point-move.point-direction-reversed","misconception_title":"출발점과 도착점을 바꾸어 이동 방향을 반대로 설명함","set_key":"grade4-semester1","signal_ids":["figure-transform.point-move"],"teacher_note":"A점과 B점의 출발·도착 순서를 바꾸어 가로 방향을 반대로 설명했습니다.","version":"1.3.0"},{"choice_id":"right-five","judgment_id":"g4s1-transform-09","misconception_key":"figure-transform.point-move.start-cell-counted","misconception_title":"출발 위치를 포함하여 이동 칸 수를 하나 크게 셈","set_key":"grade4-semester1","signal_ids":["figure-transform.point-move"],"teacher_note":"A점이 있는 출발 칸을 첫 칸으로 포함해 한 칸 크게 세었습니다.","version":"1.3.0"},{"choice_id":"right-two-down-three","judgment_id":"g4s1-transform-10","misconception_key":"figure-transform.point-move.point-direction-reversed","misconception_title":"출발점과 도착점을 바꾸어 이동 방향을 반대로 설명함","set_key":"grade4-semester1","signal_ids":["figure-transform.point-move"],"teacher_note":"A점과 B점의 출발·도착 순서를 바꾸어 두 방향을 모두 반대로 설명했습니다.","version":"1.3.0"},{"choice_id":"left-three-up-four","judgment_id":"g4s1-transform-10","misconception_key":"figure-transform.point-move.start-cell-counted","misconception_title":"출발 위치를 포함하여 이동 칸 수를 하나 크게 셈","set_key":"grade4-semester1","signal_ids":["figure-transform.point-move"],"teacher_note":"가로와 세로에서 출발 위치를 각각 포함해 두 칸 수를 모두 하나 크게 셌습니다.","version":"1.3.0"},{"choice_id":"thirty","judgment_id":"g4s1-pattern-01","misconception_key":"patterns-relations.number-rule.rule-as-addition","misconception_title":"곱셈 규칙 대신 직전에 늘어난 수만큼 더함","set_key":"grade4-semester1","signal_ids":["patterns-relations.number-rule"],"teacher_note":"6에서 18로 늘어난 12를 다음에도 한 번 더 더했습니다.","version":"1.3.0"},{"choice_id":"thirty-six","judgment_id":"g4s1-pattern-01","misconception_key":"patterns-relations.number-rule.first-term-as-factor","misconception_title":"반복되는 배수 대신 첫째 수를 곱하는 수로 사용함","set_key":"grade4-semester1","signal_ids":["patterns-relations.number-rule"],"teacher_note":"매번 3을 곱하는 규칙 대신 배열의 첫째 수 2를 곱했습니다.","version":"1.3.0"},{"choice_id":"one-hundred-eighty","judgment_id":"g4s1-pattern-02","misconception_key":"patterns-relations.number-rule.rule-as-addition","misconception_title":"곱셈 규칙 대신 직전에 늘어난 수만큼 더함","set_key":"grade4-semester1","signal_ids":["patterns-relations.number-rule"],"teacher_note":"36에서 108로 늘어난 72를 다음에도 한 번 더 더했습니다.","version":"1.3.0"},{"choice_id":"four-hundred-thirty-two","judgment_id":"g4s1-pattern-02","misconception_key":"patterns-relations.number-rule.first-term-as-factor","misconception_title":"반복되는 배수 대신 첫째 수를 곱하는 수로 사용함","set_key":"grade4-semester1","signal_ids":["patterns-relations.number-rule"],"teacher_note":"매번 3을 곱하는 규칙 대신 배열의 첫째 수 4를 곱했습니다.","version":"1.3.0"},{"choice_id":"two","judgment_id":"g4s1-pattern-03","misconception_key":"patterns-relations.figure-rule.increment-only","misconception_title":"다음 전체 개수 대신 한 단계마다 늘어나는 개수만 답함","set_key":"grade4-semester1","signal_ids":["patterns-relations.figure-rule"],"teacher_note":"정사각형이 2개씩 늘어나는 것을 찾았지만 다음 모양의 전체 개수 대신 2만 답했습니다.","version":"1.3.0"},{"choice_id":"four","judgment_id":"g4s1-pattern-03","misconception_key":"patterns-relations.figure-rule.order-as-count","misconception_title":"모양의 순서를 도형의 개수로 그대로 답함","set_key":"grade4-semester1","signal_ids":["patterns-relations.figure-rule"],